jsLib:
AES_KEY = "dzkjgfyxgshylgzm";
AES_IV = "apiupdownedcrypt";

function AESdecrypt(body) {
    const {
        java
    } = this;
    var cont = java.createSymmetricCrypto("AES/CBC/PKCS5Padding", AES_KEY, AES_IV).decryptStr(body);
    return cont;
}

function AESencode(data) {
    const {
        java
    } = this;
    var cont = java.createSymmetricCrypto("AES/CBC/PKCS5Padding", AES_KEY, AES_IV).encryptBase64(data);
    return cont;
}

function GetUrl(cmd, data) {
    const {
        java
    } = this;
    var url = `/free-video-portal/portal/${cmd},{"method": "post", body: "${this.AESencode(data)}"}`;
    return url;
}

